import{_ as r,c as a,o as e,ag as n}from"./chunks/framework.CMajxlqO.js";const g=JSON.parse('{"title":"Grundparametrar för frekvensomriktare","description":"","frontmatter":{},"headers":[],"relativePath":"08-frekvensomriktare/grundparametrar.md","filePath":"08-frekvensomriktare/grundparametrar.md","lastUpdated":1768470380000}'),s={name:"08-frekvensomriktare/grundparametrar.md"};function i(o,t,d,l,p,m){return e(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="grundparametrar-for-frekvensomriktare" tabindex="-1">Grundparametrar för frekvensomriktare <a class="header-anchor" href="#grundparametrar-for-frekvensomriktare" aria-label="Permalink to &quot;Grundparametrar för frekvensomriktare&quot;">​</a></h1><p>En frekvensomriktare (VFD - Variable Frequency Drive) måste konfigureras korrekt för att fungera säkert och effektivt med den anslutna motorn. Här går vi igenom de viktigaste grundparametrarna för SINAMICS V20.</p><h2 id="viktiga-parameterkategorier" tabindex="-1">Viktiga parameterkategorier <a class="header-anchor" href="#viktiga-parameterkategorier" aria-label="Permalink to &quot;Viktiga parameterkategorier&quot;">​</a></h2><h3 id="motordata-p0300-serien" tabindex="-1">Motordata (P0300-serien) <a class="header-anchor" href="#motordata-p0300-serien" aria-label="Permalink to &quot;Motordata (P0300-serien)&quot;">​</a></h3><p>Motordata måste ställas in korrekt för optimal prestanda:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Beskrivning</th><th>Typiskt värde</th></tr></thead><tbody><tr><td>P0304</td><td>Märkspänning motor [V]</td><td>400</td></tr><tr><td>P0305</td><td>Märkström motor [A]</td><td>Enligt motorskylt</td></tr><tr><td>P0307</td><td>Märkeffekt motor [kW]</td><td>Enligt motorskylt</td></tr><tr><td>P0308</td><td>Märkvarvtal motor [rpm]</td><td>1450 / 2900</td></tr><tr><td>P0310</td><td>Märkfrekvens motor [Hz]</td><td>50</td></tr><tr><td>P0311</td><td>Motor cos φ</td><td>Enligt motorskylt</td></tr></tbody></table><h3 id="ramp-tider-p1080-p1082" tabindex="-1">Ramp-tider (P1080/P1082) <a class="header-anchor" href="#ramp-tider-p1080-p1082" aria-label="Permalink to &quot;Ramp-tider (P1080/P1082)&quot;">​</a></h3><p>Ramp-tiderna bestämmer hur snabbt motorn accelererar och bromsar:</p><ul><li><strong>P1080</strong>: Uppramptid (acceleration) - typiskt 5-30 sekunder</li><li><strong>P1082</strong>: Nedramptid (deceleration) - typiskt 5-30 sekunder</li></ul><div class="tip custom-block"><p class="custom-block-title">Tips</p><p>Börja med längre ramptider (t.ex. 10s) och minska gradvis tills du hittar rätt balans mellan snabb respons och jämn drift.</p></div><h3 id="frekvens-och-hastighetsgranser" tabindex="-1">Frekvens- och hastighetsgränser <a class="header-anchor" href="#frekvens-och-hastighetsgranser" aria-label="Permalink to &quot;Frekvens- och hastighetsgränser&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Beskrivning</th><th>Standardvärde</th></tr></thead><tbody><tr><td>P1080</td><td>Minfrekvens [Hz]</td><td>0</td></tr><tr><td>P1082</td><td>Maxfrekvens [Hz]</td><td>50</td></tr><tr><td>P1135</td><td>OFF3 ramp (snabbstopp)</td><td>5s</td></tr></tbody></table><h2 id="driftlagen-connection-macros" tabindex="-1">Driftlägen (Connection Macros) <a class="header-anchor" href="#driftlagen-connection-macros" aria-label="Permalink to &quot;Driftlägen (Connection Macros)&quot;">​</a></h2><p>SINAMICS V20 har fördefinierade anslutnings-makron som förenklar konfigurationen:</p><ul><li><strong>Cn001</strong>: Standardinställning för fabrik</li><li><strong>Cn002</strong>: BOP-styrning (operatörspanel)</li><li><strong>Cn003</strong>: Extern styrning via klämmor</li><li><strong>Cn005</strong>: USS-kommunikation</li><li><strong>Cn006</strong>: Modbus RTU-kommunikation</li></ul><h2 id="grundlaggande-idrifttagning" tabindex="-1">Grundläggande idrifttagning <a class="header-anchor" href="#grundlaggande-idrifttagning" aria-label="Permalink to &quot;Grundläggande idrifttagning&quot;">​</a></h2><h3 id="steg-for-steg-med-bop" tabindex="-1">Steg-för-steg med BOP <a class="header-anchor" href="#steg-for-steg-med-bop" aria-label="Permalink to &quot;Steg-för-steg med BOP&quot;">​</a></h3><ol><li><strong>Ställ in motordata</strong> (P0304-P0311)</li><li><strong>Välj styrningskälla</strong> (P0700)</li><li><strong>Välj börvärdes-källa</strong> (P1000)</li><li><strong>Ställ in ramptider</strong> (P1080/P1082)</li><li><strong>Kör motoridentifiering</strong> (P1910) - valfritt men rekommenderat</li></ol><h3 id="exempel-pa-parametersattning" tabindex="-1">Exempel på parametersättning <a class="header-anchor" href="#exempel-pa-parametersattning" aria-label="Permalink to &quot;Exempel på parametersättning&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P0304 = 400     // Märkspänning 400V</span></span>
<span class="line"><span>P0305 = 2.8     // Märkström 2.8A</span></span>
<span class="line"><span>P0307 = 1.1     // Märkeffekt 1.1kW</span></span>
<span class="line"><span>P0308 = 1430    // Märkvarvtal 1430 rpm</span></span>
<span class="line"><span>P0310 = 50      // Märkfrekvens 50Hz</span></span>
<span class="line"><span>P1080 = 10      // Uppramptid 10s</span></span>
<span class="line"><span>P1082 = 10      // Nedramptid 10s</span></span></code></pre></div><h2 id="sakerhetsparametrar" tabindex="-1">Säkerhetsparametrar <a class="header-anchor" href="#sakerhetsparametrar" aria-label="Permalink to &quot;Säkerhetsparametrar&quot;">​</a></h2><p>Viktiga skyddsparametrar att konfigurera:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Funktion</th></tr></thead><tbody><tr><td>P0290</td><td>Övertemperaturskydd motor</td></tr><tr><td>P2172</td><td>Överströmsgräns</td></tr><tr><td>P2181</td><td>Underspänningsgräns</td></tr></tbody></table><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/109977897/sinamics-v20-converter" target="_blank" rel="noreferrer">SINAMICS V20 Operating Instructions</a> - Komplett manual med alla parametrar (PDF)</li><li><a href="https://support.industry.siemens.com/cs/document/109480894/simple-control-of-a-sinamics-v20-with-a-simatic-s7-1200-1500-via-uss" target="_blank" rel="noreferrer">Simple Control of SINAMICS V20 with S7-1200/1500 via USS</a> - Applikationsexempel</li></ul><h2 id="nasta-steg" tabindex="-1">Nästa steg <a class="header-anchor" href="#nasta-steg" aria-label="Permalink to &quot;Nästa steg&quot;">​</a></h2><p>När grundparametrarna är konfigurerade kan du gå vidare till:</p><ul><li><a href="./hastighetsstyrning.html">Hastighetsstyrning</a> - Sätta börvärden och skalning</li><li><a href="./start-stop.html">Start/Stop via PLC</a> - Styrning från S7-1200</li></ul>`,29)])])}const k=r(s,[["render",i]]);export{g as __pageData,k as default};
